-- Fase 85: Service Reliability Management. Observability remains the telemetry authority.
-- quality: allow-nonconcurrent-index reason=new-empty-service-reliability-tables
alter table public.plans add column if not exists service_reliability_enabled boolean not null default false;
alter table public.plans add column if not exists reliability_release_guardrails_enabled boolean not null default false;
alter table public.plans add column if not exists reliability_network_view_enabled boolean not null default false;
alter table public.plans add column if not exists reliability_backtesting_enabled boolean not null default false;

create table public.reliability_member_permissions(organization_id uuid not null references public.organizations(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,permissions text[] not null default '{reliability:view}',service_ids uuid[] not null default '{}',active boolean not null default true,updated_by uuid references auth.users(id),updated_at timestamptz not null default now(),primary key(organization_id,user_id));
create table public.reliability_service_tiers(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,key text not null,name text not null,description text,review_cadence text,requires_slo boolean not null default false,policy_ref text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,key));
create table public.reliability_services(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,key text not null,name text not null,description text,domain text not null,service_type text not null check(service_type in('api','backend_service','worker','queue','integration','customer_journey','operational_service','platform_service','external_dependency','custom')),owner_user_id uuid references auth.users(id),tier_id uuid references public.reliability_service_tiers(id),lifecycle_status text not null default 'active' check(lifecycle_status in('active','deprecated','retired')),criticality text not null check(criticality in('low','medium','high','critical')),visibility text not null default 'tenant' check(visibility in('tenant','internal','restricted')),metadata_ref jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,key),check(criticality not in('high','critical') or owner_user_id is not null));
create table public.reliability_service_dependencies(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,service_id uuid not null references public.reliability_services(id) on delete cascade,dependency_service_id uuid references public.reliability_services(id) on delete cascade,external_provider_ref text,dependency_type text not null check(dependency_type in('hard','soft','degraded_mode','asynchronous','optional')),criticality text not null default 'medium' check(criticality in('low','medium','high','critical')),fallback_mode text,created_at timestamptz not null default now(),check(dependency_service_id is not null or external_provider_ref is not null),check(dependency_service_id is null or dependency_service_id<>service_id),unique(service_id,dependency_service_id,external_provider_ref));
create table public.reliability_journeys(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,key text not null,name text not null,description text,owner_user_id uuid not null references auth.users(id),criticality text not null check(criticality in('low','medium','high','critical')),status text not null default 'active' check(status in('draft','active','deprecated','retired')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,key));
create table public.reliability_journey_steps(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,journey_id uuid not null references public.reliability_journeys(id) on delete cascade,sequence integer not null check(sequence>0),service_id uuid not null references public.reliability_services(id),step_key text not null,critical boolean not null default true,success_condition_ref text not null,latency_budget_ms integer check(latency_budget_ms is null or latency_budget_ms>0),created_at timestamptz not null default now(),unique(journey_id,sequence),unique(journey_id,step_key));
create table public.sli_measurement_definitions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,key text not null,source_type text not null check(source_type in('observability_metric','trace_event','domain_event_counter','queue_metric','integration_metric','hardware_metric','custom_adapter')),source_ref text not null,query_template_ref text,parameters jsonb not null default '{}',freshness_requirement_seconds integer not null default 600 check(freshness_requirement_seconds between 10 and 86400),status text not null default 'active' check(status in('draft','active','deprecated','retired')),created_at timestamptz not null default now(),unique(organization_id,key));
create table public.service_level_indicators(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,service_id uuid references public.reliability_services(id) on delete cascade,journey_id uuid references public.reliability_journeys(id) on delete cascade,key text not null,name text not null,sli_type text not null check(sli_type in('availability','success_rate','latency','correctness','throughput','queue_delay','completion','freshness_operational','custom')),measurement_definition_id uuid not null references public.sli_measurement_definitions(id),good_event_definition jsonb not null,valid_event_definition jsonb not null,aggregation text not null,unit text not null,source text not null,status text not null default 'draft' check(status in('draft','active','deprecated','retired')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check((service_id is not null)::integer+(journey_id is not null)::integer=1),unique(organization_id,key));
create table public.sli_measurements(id bigint generated always as identity primary key,organization_id uuid not null references public.organizations(id) on delete cascade,sli_id uuid not null references public.service_level_indicators(id) on delete cascade,bucket_start timestamptz not null,bucket_end timestamptz not null,good_events bigint not null check(good_events>=0),valid_events bigint not null check(valid_events>=0 and good_events<=valid_events),ratio numeric,percentile_value numeric,data_quality text not null check(data_quality in('complete','partial','stale','missing','invalid')),source_timestamp timestamptz not null,created_at timestamptz not null default now(),unique(sli_id,bucket_start,bucket_end),check(ratio is null or ratio between 0 and 1));
create table public.service_level_objectives(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,sli_id uuid not null references public.service_level_indicators(id) on delete cascade,name text not null,target_value numeric not null check(target_value>0 and target_value<=1),comparison text not null check(comparison in('gte','lte')),window_type text not null check(window_type in('rolling','calendar')),window_length text not null,effective_from timestamptz not null,effective_until timestamptz,status text not null default 'draft' check(status in('draft','active','deprecated','retired')),owner_user_id uuid not null references auth.users(id),policy_ref text,version integer not null check(version>0),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(sli_id,version),check(effective_until is null or effective_until>effective_from));
create table public.slo_exclusion_policies(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,slo_id uuid not null references public.service_level_objectives(id) on delete cascade,name text not null,exclusion_type text not null check(exclusion_type in('planned_maintenance','test_traffic','synthetic_probe','known_provider_outage','internal_admin_traffic','custom')),view_scope text not null default 'internal' check(view_scope in('internal','customer','both')),starts_at timestamptz not null,ends_at timestamptz not null,reason text not null,approved_by uuid not null references auth.users(id),created_at timestamptz not null default now(),check(ends_at>starts_at));
create table public.slo_evaluations(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,slo_id uuid not null references public.service_level_objectives(id) on delete cascade,slo_version integer not null,window_start timestamptz not null,window_end timestamptz not null,view_scope text not null check(view_scope in('customer','internal')),achieved_value numeric,target_value numeric not null,compliance_status text not null check(compliance_status in('meeting','at_risk','breached','unknown')),good_events bigint not null default 0,valid_events bigint not null default 0,budget_consumed numeric,budget_remaining numeric,data_quality text not null check(data_quality in('complete','partial','stale','missing','invalid')),source_as_of timestamptz,evaluated_at timestamptz not null default now(),created_at timestamptz not null default now(),unique(slo_id,slo_version,window_start,window_end,view_scope));
create table public.error_budgets(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,slo_id uuid not null references public.service_level_objectives(id) on delete cascade,slo_version integer not null,window_start timestamptz not null,window_end timestamptz not null,allowed_bad_events numeric,consumed_bad_events numeric,remaining_bad_events numeric,consumption_percent numeric,remaining_percent numeric,status text not null check(status in('healthy','attention','at_risk','exhausted','unknown')),data_as_of timestamptz not null,created_at timestamptz not null default now(),unique(slo_id,slo_version,window_start,window_end));
create table public.reliability_burn_rates(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,slo_id uuid not null references public.service_level_objectives(id) on delete cascade,slo_version integer not null,window_label text not null,window_start timestamptz not null,window_end timestamptz not null,actual_error_rate numeric,allowed_error_rate numeric,burn_rate numeric,status text not null check(status in('sustainable','burning','unknown')),data_quality text not null,calculated_at timestamptz not null default now(),created_at timestamptz not null default now(),unique(slo_id,slo_version,window_label,window_end));
create table public.reliability_policies(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,service_id uuid references public.reliability_services(id) on delete cascade,slo_id uuid references public.service_level_objectives(id) on delete cascade,version integer not null default 1,burn_thresholds jsonb not null default '{}',budget_thresholds jsonb not null default '{}',release_behavior text not null check(release_behavior in('notify_only','require_review','require_approval','block_noncritical_release','freeze_feature_rollout')),incident_behavior jsonb not null default '{}',review_behavior jsonb not null default '{}',active boolean not null default true,effective_from timestamptz not null default now(),effective_until timestamptz,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),check(service_id is not null or slo_id is not null));
create table public.reliability_alerts(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,service_id uuid references public.reliability_services(id) on delete cascade,slo_id uuid references public.service_level_objectives(id) on delete cascade,alert_type text not null check(alert_type in('fast_burn','slow_burn','budget_low','budget_exhausted','slo_breach','measurement_missing','dependency_degraded')),dedupe_key text not null,severity text not null check(severity in('info','warning','high','critical')),status text not null default 'new' check(status in('new','acknowledged','resolved','suppressed')),window_context jsonb not null default '{}',notification_ref text,noc_alert_id uuid references public.network_alerts(id) on delete set null,created_at timestamptz not null default now(),resolved_at timestamptz,unique(organization_id,dedupe_key,status));
create table public.reliability_incident_impacts(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,incident_id uuid not null references public.operational_incidents(id) on delete cascade,service_id uuid not null references public.reliability_services(id),slo_id uuid references public.service_level_objectives(id),window_start timestamptz not null,window_end timestamptz not null,bad_event_count bigint,budget_consumed numeric,attribution_status text not null default 'annotated' check(attribution_status in('estimated','annotated','reviewed')),overlap_strategy text not null default 'deduplicate_bucket',created_at timestamptz not null default now(),unique(incident_id,service_id,slo_id,window_start,window_end));
create table public.reliability_release_guardrail_checks(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,release_ref text not null,service_id uuid not null references public.reliability_services(id),policy_id uuid references public.reliability_policies(id),decision text not null check(decision in('proceed','proceed_with_warning','require_approval','restricted','block_nonessential')),reasons jsonb not null default '[]',budget_snapshot jsonb not null default '{}',exception_type text,approval_ref text,checked_at timestamptz not null default now(),created_at timestamptz not null default now(),unique(organization_id,release_ref,service_id));
create table public.reliability_change_freezes(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,scope_type text not null check(scope_type in('service','domain','organization','platform')),scope_id text not null,starts_at timestamptz not null,ends_at timestamptz not null,reason text not null,status text not null default 'scheduled' check(status in('scheduled','active','expired','cancelled')),exceptions text[] not null default '{incident_remediation,security_patch,reliability_fix,emergency}',approved_by uuid not null references auth.users(id),created_at timestamptz not null default now(),check(ends_at>starts_at));
create table public.reliability_waivers(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,service_id uuid references public.reliability_services(id),slo_id uuid references public.service_level_objectives(id),waiver_type text not null,reason text not null,starts_at timestamptz not null,expires_at timestamptz not null,approver_id uuid not null references auth.users(id),incident_ref uuid references public.operational_incidents(id),change_ref text,status text not null default 'active' check(status in('active','expired','revoked')),created_at timestamptz not null default now(),check(expires_at>starts_at));
create table public.reliability_maintenance_windows(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,service_id uuid references public.reliability_services(id),starts_at timestamptz not null,ends_at timestamptz not null,scope jsonb not null default '{}',planned boolean not null default true,expected_impact text,exclusion_policy_id uuid references public.slo_exclusion_policies(id),status text not null default 'scheduled',created_at timestamptz not null default now(),check(ends_at>starts_at));
create table public.reliability_backtest_runs(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,sli_id uuid not null references public.service_level_indicators(id),proposed_target numeric not null,window_start timestamptz not null,window_end timestamptz not null,achieved_value numeric,would_meet boolean,budget_consumption_percent numeric,data_quality text not null,status text not null default 'completed',requested_by uuid not null references auth.users(id),created_at timestamptz not null default now());
create table public.reliability_reviews(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,service_id uuid not null references public.reliability_services(id),review_type text not null check(review_type in('weekly','monthly','post_incident','quarterly')),review_period tstzrange not null,slo_summary jsonb not null default '[]',incidents jsonb not null default '[]',budget_state jsonb not null default '{}',top_failure_modes jsonb not null default '[]',decisions jsonb not null default '[]',follow_up_refs jsonb not null default '[]',status text not null default 'draft' check(status in('draft','in_review','completed')),created_by uuid not null references auth.users(id),created_at timestamptz not null default now());
create table public.reliability_audit_events(id bigint generated always as identity primary key,organization_id uuid not null references public.organizations(id) on delete cascade,actor_id uuid references auth.users(id),event_type text not null,entity_type text not null,entity_id uuid,reason text,before_state_redacted jsonb,after_state_redacted jsonb,correlation_id uuid not null default gen_random_uuid(),created_at timestamptz not null default now());

create index reliability_services_org_status_idx on public.reliability_services(organization_id,lifecycle_status,criticality);
create index reliability_dependencies_service_idx on public.reliability_service_dependencies(organization_id,service_id,criticality);
create index sli_measurements_window_idx on public.sli_measurements(organization_id,sli_id,bucket_end desc);
create index slo_active_window_idx on public.service_level_objectives(organization_id,status,effective_from desc);
create index slo_evaluations_recent_idx on public.slo_evaluations(organization_id,slo_id,evaluated_at desc);
create index error_budgets_status_idx on public.error_budgets(organization_id,status,data_as_of desc);
create index burn_rates_recent_idx on public.reliability_burn_rates(organization_id,slo_id,calculated_at desc);
create index reliability_alerts_active_idx on public.reliability_alerts(organization_id,status,severity,created_at desc);
create index reliability_guardrails_release_idx on public.reliability_release_guardrail_checks(organization_id,release_ref,checked_at desc);
create index reliability_audit_org_idx on public.reliability_audit_events(organization_id,created_at desc);

do $$ declare t text; begin foreach t in array array['reliability_member_permissions','reliability_service_tiers','reliability_services','reliability_service_dependencies','reliability_journeys','reliability_journey_steps','sli_measurement_definitions','service_level_indicators','sli_measurements','service_level_objectives','slo_exclusion_policies','slo_evaluations','error_budgets','reliability_burn_rates','reliability_policies','reliability_alerts','reliability_incident_impacts','reliability_release_guardrail_checks','reliability_change_freezes','reliability_waivers','reliability_maintenance_windows','reliability_backtest_runs','reliability_reviews','reliability_audit_events'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from anon,authenticated,public',t);execute format('grant all on public.%I to service_role',t);execute format('create policy %I on public.%I for all to service_role using(true) with check(true)',left('reliability_service_'||t,63),t);end loop;end $$;
revoke all on sequence public.sli_measurements_id_seq,public.reliability_audit_events_id_seq from public,anon,authenticated;
grant usage,select on sequence public.sli_measurements_id_seq,public.reliability_audit_events_id_seq to service_role;

create or replace view public.service_reliability_overview with(security_invoker=true) as
select s.organization_id,count(*) filter(where s.criticality in('high','critical') and s.lifecycle_status='active') critical_services,count(distinct o.id) filter(where o.status='active') active_slos,count(distinct e.slo_id) filter(where e.compliance_status='meeting') slos_meeting,count(distinct e.slo_id) filter(where e.compliance_status='at_risk') slos_at_risk,count(distinct e.slo_id) filter(where e.compliance_status='breached') slo_breaches,count(distinct b.slo_id) filter(where b.status in('at_risk','exhausted')) budgets_low,max(e.evaluated_at) data_as_of
from public.reliability_services s left join public.service_level_indicators i on i.service_id=s.id left join public.service_level_objectives o on o.sli_id=i.id left join lateral(select * from public.slo_evaluations x where x.slo_id=o.id order by x.evaluated_at desc limit 1)e on true left join lateral(select * from public.error_budgets x where x.slo_id=o.id order by x.data_as_of desc limit 1)b on true group by s.organization_id;
revoke all on public.service_reliability_overview from public,anon,authenticated;grant select on public.service_reliability_overview to service_role;

comment on table public.sli_measurements is 'Aggregates sourced from Phase 26 Observability; never raw trace duplication.';
comment on table public.service_level_objectives is 'Versioned service/product reliability objectives; Phase 76 remains owner of data reliability.';
comment on table public.reliability_release_guardrail_checks is 'Advisory/policy decisions only; no blind rollback or runtime order dependency.';
insert into public.search_navigation_registry(id,title,route,keywords,module,required_permission,icon,position,customer_visible) values('service-reliability','Confiabilidade','/painel/operacoes/confiabilidade',array['slo','sli','error budget','burn rate','serviços','confiabilidade'],'service_reliability','search:global','◌',38,true) on conflict(id) do update set title=excluded.title,route=excluded.route,keywords=excluded.keywords,module=excluded.module,position=excluded.position,customer_visible=true;
